all_pass = True
for idx, (exi, egamma, ri_file) in enumerate(sampled_gammas, 1):
    exf = exi - egamma
    
    # Verify in CSV reference
    csv_record = csv_data.get(exi, {}).get(egamma, None)
    
    if csv_record is None:
        print(f'{idx}. ✗ Exi={exi}, Egamma={egamma}, RI={ri_file}')
        print(f'   ERROR: Gamma NOT FOUND in CSV reference!')
        all_pass = False
    else:
        csv_exf, csv_ri = csv_record
        if csv_exf == exf and csv_ri == ri_file:
            print(f'{idx}. ✓ Exi={exi}, Egamma={egamma} → Exf={exf}, RI={ri_file} [MATCH]')
        else:
            print(f'{idx}. ✗ Exi={exi}, Egamma={egamma}, RI={ri_file}')
            if csv_exf != exf:
                print(f'   ERROR: Exf mismatch - expected {csv_exf}, got {exf}')
            if csv_ri != ri_file:
                print(f'   ERROR: RI mismatch - expected {csv_ri}, got {ri_file}')
            all_pass = False

